function validate([m, n, hFences, vFences]) {
  if (!Number.isInteger(m) || !Number.isInteger(n) || m < 3 || n < 3 || m > 1e9 || n > 1e9) return 'm and n are whole numbers from 3 to 10^9.';
  if (!Array.isArray(hFences) || hFences.length < 1 || hFences.length > 600) return 'hFences needs 1 to 600 values.';
  if (!Array.isArray(vFences) || vFences.length < 1 || vFences.length > 600) return 'vFences needs 1 to 600 values.';
  if (hFences.some(h => !Number.isInteger(h) || h <= 1 || h >= m)) return 'Each horizontal fence lies strictly between 1 and m.';
  if (vFences.some(v => !Number.isInteger(v) || v <= 1 || v >= n)) return 'Each vertical fence lies strictly between 1 and n.';
  if (new Set(hFences).size !== hFences.length) return 'hFences values must be distinct.';
  if (new Set(vFences).size !== vFences.length) return 'vFences values must be distinct.';
  return null;
}

