function maximizeSquareArea(m, n, hFences, vFences) {
  const MOD = 1000000007n;
  const rows = [1, ...hFences, m];
  const cols = [1, ...vFences, n];
  const heights = new Set();
  for (let i = 0; i < rows.length; i++) {
    for (let j = i + 1; j < rows.length; j++) {
      heights.add(Math.abs(rows[i] - rows[j]));
    }
  }
  let side = -1;
  for (let i = 0; i < cols.length; i++) {
    for (let j = i + 1; j < cols.length; j++) {
      const width = Math.abs(cols[i] - cols[j]);
      if (width > side && heights.has(width)) {
        side = width;
      }
    }
  }
  if (side === -1) {
    return -1;
  }
  return Number(BigInt(side) * BigInt(side) % MOD);
}

