function maximizeSquareArea(m, n, hFences, vFences) {
  // Try every pair of horizontal lines against every pair of vertical lines.
  const xs = [1, m, ...hFences].sort((a, b) => a - b);
  const ys = [1, n, ...vFences].sort((a, b) => a - b);
  let best = 0;
  for (let a = 0; a < xs.length; a++)
    for (let b = a + 1; b < xs.length; b++)
      for (let c = 0; c < ys.length; c++)
        for (let d = c + 1; d < ys.length; d++)
          if (xs[b] - xs[a] === ys[d] - ys[c]) best = Math.max(best, xs[b] - xs[a]);
  if (best === 0) return -1;
  // Square modulo 1e9+7 by repeated doubling, so no intermediate value exceeds 2^53.
  const P = 1000000007;
  let result = 0, base = best % P, times = best;
  while (times > 0) {
    if (times % 2 === 1) result = (result + base) % P;
    base = (base * 2) % P;
    times = Math.floor(times / 2);
  }
  return result;
}

