function generate(rand, size) {
  const pick = (limit, count) => {
    // count distinct values strictly between 1 and limit.
    const chosen = new Set();
    while (chosen.size < count) chosen.add(2 + Math.floor(rand() * (limit - 2)));
    return [...chosen];
  };
  if (size === 'large') {
    const shape = Math.floor(rand() * 3);
    if (shape === 0) {
      const m = 1000000000 - Math.floor(rand() * 1000), n = 1000000000 - Math.floor(rand() * 1000);
      return [m, n, pick(m, 600), pick(n, 600)];
    }
    if (shape === 1) {
      const m = 3 + Math.floor(rand() * 5000), n = 3 + Math.floor(rand() * 5000);
      return [m, n, pick(m, Math.min(600, m - 2)), pick(n, Math.min(600, n - 2))];
    }
    const m = 100000 + Math.floor(rand() * 900000), n = m + Math.floor(rand() * 1000);
    return [m, n, pick(m, 600), pick(n, 600)];
  }
  const m = 3 + Math.floor(rand() * 15), n = 3 + Math.floor(rand() * 15);
  return [m, n, pick(m, 1 + Math.floor(rand() * Math.min(5, m - 2))), pick(n, 1 + Math.floor(rand() * Math.min(5, n - 2)))];
}
